import pathlib
ROOT = pathlib.Path('/Users/guillaumeloulier/PhpstormProjects/oss/elephc/.claude/worktrees/streams-csv-signature')
p = ROOT / 'src/codegen_support/runtime/io/fopen.rs'
t = p.read_text()

old = 'pub(crate) fn emit_refuse_when_file_wrapper_disabled(emitter: &mut Emitter, failure: i64) {'
new = '''/// What a guarded helper hands back while `file://` is unregistered.
///
/// The two shapes are not interchangeable: a PREDICATE answers in x0/rax alone, while the
/// `int|false` helpers answer a PAIR — the value and a SUCCESS FLAG that the caller's boxer reads
/// to decide between an integer and php `false`. Setting only the value there leaves the flag
/// holding whatever the register happened to carry, and the refusal boxes as the integer -1
/// instead of `false`, which is exactly what `filemtime` did on the first attempt.
#[derive(Clone, Copy)]
pub(crate) enum DisabledWrapperAnswer {
    /// x0/rax alone; `false` for a predicate is zero.
    Predicate(i64),
    /// x0/rax plus a cleared success flag in x1/rdx, which the caller boxes as php `false`.
    IntOrFalse,
}

pub(crate) fn emit_refuse_when_file_wrapper_disabled(
    emitter: &mut Emitter,
    answer: DisabledWrapperAnswer,
) {'''
assert t.count(old) == 1, 'emitter signature not found'
t = t.replace(old, new, 1)

old = '''            emitter.instruction(&format!("mov x0, #{failure}"));                // php answers this while it is not
            emitter.instruction("ret");'''
new = '''            match answer {
                DisabledWrapperAnswer::Predicate(value) => {
                    emitter.instruction(&format!("mov x0, #{value}"));          // php answers this while it is not
                }
                DisabledWrapperAnswer::IntOrFalse => {
                    emitter.instruction("mov x0, #0");                          // the payload is unused for a refusal
                    emitter.instruction("mov x1, #0");                          // clear the flag: the caller boxes php false
                }
            }
            emitter.instruction("ret");'''
assert t.count(old) == 1
t = t.replace(old, new, 1)

old = '''            emitter.instruction(&format!("mov rax, {failure}"));                // php answers this while it is not
            emitter.instruction("ret");'''
new = '''            match answer {
                DisabledWrapperAnswer::Predicate(value) => {
                    emitter.instruction(&format!("mov rax, {value}"));          // php answers this while it is not
                }
                DisabledWrapperAnswer::IntOrFalse => {
                    emitter.instruction("xor eax, eax");                        // the payload is unused for a refusal
                    emitter.instruction("xor edx, edx");                        // clear the flag: the caller boxes php false
                }
            }
            emitter.instruction("ret");'''
assert t.count(old) == 1
t = t.replace(old, new, 1)
p.write_text(t)
print('fopen.rs: the guard expresses both return shapes')

p = ROOT / 'src/codegen_support/runtime/io/stat.rs'
t = p.read_text()
t = t.replace('emit_refuse_when_file_wrapper_disabled(emitter, 0);',
              'emit_refuse_when_file_wrapper_disabled(emitter, super::fopen::DisabledWrapperAnswer::Predicate(0));')
t = t.replace('emit_refuse_when_file_wrapper_disabled(emitter, -1);',
              'emit_refuse_when_file_wrapper_disabled(emitter, super::fopen::DisabledWrapperAnswer::IntOrFalse);')
p.write_text(t)
print('stat.rs: predicates and int|false helpers use their own shape')
